374 | export const getAllTransactionsForUserByObj = curry((userId: string, query?: object) => {
375 |   const queryWithoutFilterFields = query && getQueryWithoutFilterFields(query);
376 | 
377 |   const queryFields = queryWithoutFilterFields || query;
378 | 
379 |   const userTransactions = flatMap(getTransactionsByObj)([
380 |     {
381 |       receiverId: userId,
382 |       ...queryFields,
383 |     },
384 |     {
385 |       senderId: userId,
386 |       ...queryFields,
387 |     },
388 |   ]);
389 | 
390 |   if (query && (hasDateQueryFields(query) || hasAmountQueryFields(query))) {
391 |     const { dateRangeStart, dateRangeEnd } = getDateQueryFields(query);
392 |     const { amountMin, amountMax } = getAmountQueryFields(query);
393 | 
394 |     return flow(
395 |       transactionsWithinDateRange(dateRangeStart!, dateRangeEnd!),
396 |       transactionsWithinAmountRange(amountMin!, amountMax!)
