304 | export const createSeedTransactions = (seedUsers: User[], seedBankAccounts: BankAccount[]) =>
305 |   flattenDepth(
306 |     2,
307 |     map((user: User): Transaction[] => {
308 |       const accounts = getBankAccountsByUserId(seedBankAccounts, user.id);
309 | 
310 |       return flattenDepth(
311 |         2,
312 |         map((account: BankAccount): Transaction[] => {
313 |           const randomUser = getOtherRandomUser(seedUsers, user.id);
314 |           // @ts-ignore
315 |           const payments = times(() => createPayment(account, user, randomUser), paymentsPerUser);
316 |           // @ts-ignore
317 |           const requests = times(() => createRequest(account, user, randomUser), requestsPerUser);
318 | 
319 |           const allScenarios = flattenDeep(concat(payments, requests));
320 |           const requestedTransaction = filter(requestScenarios[0], allScenarios)[0];
321 |           const chargedTransaction = filter(requestScenarios[1], allScenarios)[0];
322 |           const paidTransaction = filter(paymentScenarios[1], allScenarios)[0];
323 | 
324 |           const testTransactions = [paidTransaction, requestedTransaction, chargedTransaction];
325 | 
326 |           const remainingScenarios = differenceBy(get("id"), allScenarios, testTransactions);
327 | 
328 |           // @ts-ignore
329 |           return flattenDeep(concat(testTransactions, remainingScenarios));
330 |         })(accounts)
331 |       );
332 |     })(seedUsers)
333 |   );

