159 |           .then(({ data }) => {
160 |             history.push("/");
161 |             return data;
162 |           })
163 |           .catch((error) => {
164 |             throw new Error("Username or password is invalid");
165 |           });
166 |       },
167 |       getOktaUserProfile: /* istanbul ignore next */ (ctx, event: any) => {
168 |         // Map Okta User fields to our User Model
169 |         const user = {
170 |           id: event.user.sub,
171 |           email: event.user.email,
172 |           firstName: event.user.given_name,
173 |           lastName: event.user.family_name,
174 |           username: event.user.preferred_username,
175 |         };
176 | 
177 |         // Set Access Token in Local Storage for API calls
178 |         localStorage.setItem(process.env.VITE_AUTH_TOKEN_NAME!, event.token);
