204 | const getDateParts = (isoString: string) => {
205 |   const date = parseISO(isoString);
206 |   const day = Number(formatInTimeZone(date, timezone, "d"));
207 |   const month = Number(formatInTimeZone(date, timezone, "M")) - 1;
208 |   const year = Number(formatInTimeZone(date, timezone, "Y"));
209 |   const hour = Number(formatInTimeZone(date, timezone, "H"));
210 |   const minute = Number(formatInTimeZone(date, timezone, "m"));
211 |   const second = Number(formatInTimeZone(date, timezone, "s"));
212 |   const ms = Number(formatInTimeZone(date, timezone, "SSS"));
213 |   return { day, month, year, hour, minute, second, ms };
214 | };

