235 | export function localDateToUTCISOString(localDate: ValuePiece) {
236 |   if (!(localDate instanceof Date)) return new Date().toISOString();
237 |   const utcDate = new Date(
238 |     Date.UTC(
239 |       localDate.getFullYear(),
240 |       localDate.getMonth(),
241 |       localDate.getDate(),
242 |       localDate.getHours(),
243 |       localDate.getMinutes(),
244 |       localDate.getSeconds(),
245 |       localDate.getMilliseconds()
246 |     )
247 |   );
248 |   return utcDate.toISOString();
249 | }

